  "question": "Given an array of integers, write a function that returns True if any value appears at least twice in the array, and False if every element is distinct.",
  "function_name": "contains_duplicate",
  "signature": "def contains_duplicate(nums: list[int]) -> bool",
  "checker": "exact",
  "reference_solution": "def contains_duplicate(nums: list[int]) -> bool:\n    seen = set()\n    for n in nums:\n        if n in seen:\n            return True\n        seen.add(n)\n    return False",
  "cases": [
    {
      "args_json": "[[1, 2, 3, 1]]",
      "expected_json": "true",
      "note": "Duplicate element 1 at start and end"
    },
