      "args_json": "[[1, 2, 3, 4]]",
      "expected_json": "false",
      "note": "All elements are distinct"
    },
    {
      "args_json": "[[1, 1, 1, 3, 3, 4, 3, 2, 4, 2]]",
      "expected_json": "true",
      "note": "Multiple duplicates"
    },
    {
      "args_json": "[[]]",
      "expected_json": "false",
      "note": "Empty list edge case"
    },
    {
      "args_json": "[[5]]",
      "expected_json": "false",
      "note": "Single element list"
    },
    {
      "args_json": "[[5, 5]]",
      "expected_json": "true",
      "note": "Two identical elements"
    }
  ]
